#include <iostream>

class Box {
private:
    int m_value{ 0 };

public:
    int getValue() const { return m_value; }
    int& value() { return m_value; }
};

int main() {
    int init, a, b;
    std::cin >> init >> a >> b;

    Box box;
    box.value() = init;   // write through the returned reference
    box.value() += a;     // modify through the returned reference
    box.value() -= b;

    std::cout << box.getValue() << '\n';

    return 0;
}

