solution_code:
#include <iostream>
#include <string>

class Label {
private:
    std::string m_text{};

public:
    const std::string& getText() const { return m_text; }
    std::string& text() { return m_text; }
};

int main() {
    std::string base, suffix;
    std::cin >> base >> suffix;

    Label label;
    label.text() = base;      // write through the returned reference
    label.text() += suffix;   // append through the returned reference

    std::cout << label.getText() << '\n';

    return 0;
}
